shell_commands:
git diff --stat; echo '---SPLIT---'; node -e '
const {readFileSync} = require("fs");
const specs = ["specs/hal-engine-conversation-list/spec.md","specs/hal-engine-websocket-protocol/spec.md","specs/hal-engine-session-resume/spec.md","specs/hal-engine-npm-release/spec.md","specs/hal-engine-single-terminal-frame/spec.md"];
const targets = {
  "src/transport/conversationList.acceptance.test.ts": readFileSync("src/transport/conversationList.acceptance.test.ts","utf8").split("\n"),
  "src/transport/ws/validation.test.ts": readFileSync("src/transport/ws/validation.test.ts","utf8").split("\n"),
  "src/transport/sessionResume.test.ts": readFileSync("src/transport/sessionResume.test.ts","utf8").split("\n"),
};
let bad = 0, checked = 0;
for (const spec of specs) {
  const text = readFileSync(spec, "utf8");
  const re = /\]\((\.\.\/)+?(src\/[^)#]+\.ts)#L(\d+)\)/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const path = m[2], line = Number(m[3]);
    const lines = targets[path];
    if (!lines) continue;
    checked++;
    const content = (lines[line-1]||"").trim();
    const ok = /\b(it|test|describe)\(/.test(content);
    if (!ok) { bad++; console.log("NOT-AN-IT", spec, path+"#L"+line, JSON.stringify(content.slice(0,60))); }
  }
}
console.log(`checked ${checked} anchors into edited files, ${bad} not on a test declaration`);
'

node -e '
const {readFileSync} = require("fs");
const specs = ["specs/hal-engine-conversation-list/spec.md","specs/hal-engine-websocket-protocol/spec.md","specs/hal-engine-session-resume/spec.md","specs/hal-engine-npm-release/spec.md","specs/hal-engine-single-terminal-frame/spec.md"];
const targets = {
  "src/transport/conversationList.acceptance.test.ts": readFileSync("src/transport/conversationList.acceptance.test.ts","utf8").split("\n"),
  "src/transport/ws/validation.test.ts": readFileSync("src/transport/ws/validation.test.ts","utf8").split("\n"),
  "src/transport/sessionResume.test.ts": readFileSync("src/transport/sessionResume.test.ts","utf8").split("\n"),
};
let bad = 0, checked = 0;
for (const spec of specs) {
  const text = readFileSync(spec, "utf8");
  const re = /\[validated by: ([^\]]+)\]\((?:\.\.\/)+?(src\/[^)#]+\.ts)#L(\d+)\)/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const name = m[1], path = m[2], line = Number(m[3]);
    const lines = targets[path];
    if (!lines) continue;
    checked++;
    const title = ((lines[line-1]||"").match(/it\(\x27([^\x27]+)\x27/)||[])[1];
    if (title !== name) { bad++; console.log("MISMATCH", spec); console.log("  cited:", name); console.log("  title:", title); }
  }
}
console.log(`checked ${checked} citation names, ${bad} mismatches`);
'
